script:
(function () {
  'use strict';
  // After-tax value of a REIT distribution, split into its three tax parts (Form 1099-DIV):
  //   Ordinary REIT dividends (box 5, "section 199A dividends"): taxed at your ordinary bracket, but
  //     20% of them is deductible (IRC 199A(b)(1)(B)), so the federal rate on them is
  //     bracket x (1 - 0.20) - e.g. 37% -> 29.6%, 24% -> 19.2%. The REIT part of the deduction has
  //     no wage or income-threshold limits; it is capped at 20% of (taxable income - net capital
  //     gain), which the calculator applies.
  //   Capital gain distributions (box 2a): 0/15/20% by taxable income.
  //   Return of capital (box 3, nondividend): not taxed now; it lowers your cost basis, so it is
  //     taxed later as a capital gain when you sell.
  //   Optional 3.8% net investment income tax on the ordinary and capital gain parts (the 199A
  //     deduction does not reduce it) and a flat state rate (most states do not allow the 199A
  //     deduction, so the state rate applies to the full taxable part).
  // Results use marginal rates at the taxable income you enter.
  //   After-tax yield = y x (1 - weighted tax rate)
  //   Tax-equivalent yield (fully taxable interest such as a bond or CD) = after-tax yield /
  //     (1 - (bracket + state + NIIT))
  //   Equivalent qualified-dividend yield = after-tax yield / (1 - (0/15/20% + state + NIIT))
  // Verified (Node scratch test, tests/rt.test.js, against hand calculations):
  //   Single, $100,000 taxable income (22% bracket, 15% gain rate), 6% yield, 100% ordinary, no state:
  //     federal rate 17.6%, after-tax 4.944%, tax-equivalent 4.944 / 0.78 = 6.338%,
  //     qualified-dividend equivalent 4.944 / 0.85 = 5.816%.
  //   Joint, $900,000 (37%), 70% ordinary / 10% gain / 20% return of capital, 5% state, NIIT:
  //     weighted rate 0.7 x (0.296 + 0.05 + 0.038) + 0.1 x (0.20 + 0.05 + 0.038) = 29.76%.
  //   Taxable income $20,000 with $40,000 of REIT ordinary dividends: deduction capped at
  //     20% x 20,000 = $4,000 (not $8,000), so only 10% of the dividends is deducted.
  //
  // ---- 2026 FEDERAL CONSTANTS (tax year 2026) -------------------------------------------
  // Brackets and capital gains breakpoints: IRS Rev. Proc. 2025-32 sections 4.01 and 4.03 (as
  //   amended by P.L. 119-21); same constants as tax-equivalent-yield-calculator and tax-harvesting.
  // Section 199A 20% deduction for qualified REIT dividends: IRC 199A(b)(1)(B); P.L. 119-21
  //   sec. 70105 rewrote 199A(i), which had ended the deduction after 2025, so it is permanent.
  // NIIT: IRC 1411, 3.8%, thresholds not indexed.
  var TAX_YEAR = 2026;
  var BRACKETS = { // upper limit of each band; rates 10, 12, 22, 24, 32, 35, 37%
    single: [12400, 50400, 105700, 201775, 256225, 640600],
    mfj:    [24800, 100800, 211400, 403550, 512450, 768700],
    mfs:    [12400, 50400, 105700, 201775, 256225, 384350],
    hoh:    [17700, 67450, 105700, 201750, 256200, 640600]
  };
  var RATES = [0.10, 0.12, 0.22, 0.24, 0.32, 0.35, 0.37];
  var CG_BREAKS = { single: [49450, 545500], mfj: [98900, 613700], hoh: [66200, 579600], mfs: [49450, 306850] };
  var REIT_DEDUCTION = 0.20, NIIT_RATE = 0.038;
  // ---------------------------------------------------------------------------------------

  var money = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', minimumFractionDigits: 2, maximumFractionDigits: 2 });
  var money0 = new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 });

  function marginalRate(income, s) {
    var limits = BRACKETS[s];
    for (var i = 0; i < limits.length; i++) if (income <= limits[i]) return RATES[i];
    return RATES[RATES.length - 1];
  }
  function gainRate(income, s) {
    var b = CG_BREAKS[s];
    return income <= b[0] ? 0 : income <= b[1] ? 0.15 : 0.20;
  }
  function pct(x, d) { return (x * 100).toFixed(d === undefined ? 2 : d) + '%'; }

  // o: { status, income, yield, ordShare, cgShare, state, niit, amount }
  function analyse(o, bracketOverride) {
    var fed = bracketOverride !== undefined ? bracketOverride : marginalRate(o.income, o.status);
    var cg = gainRate(o.income, o.status);
    var niit = o.niit ? NIIT_RATE : 0;
    var rocShare = Math.max(0, 1 - o.ordShare - o.cgShare);
    var dist = o.amount * o.yield;
    var ordinary = dist * o.ordShare, gains = dist * o.cgShare;
    var maxDed = REIT_DEDUCTION * Math.max(0, o.income - gains);
    var deduction = Math.min(REIT_DEDUCTION * ordinary, maxDed);
    var dedShare = ordinary > 0 ? deduction / ordinary : REIT_DEDUCTION;
    var ordRate = fed * (1 - dedShare);
    var ordTotal = ordRate + o.state + niit, cgTotal = cg + o.state + niit;
    var weighted = o.ordShare * ordTotal + o.cgShare * cgTotal;
    var after = o.yield * (1 - weighted);
    var fullRate = fed + o.state + niit, qualRate = cg + o.state + niit;
    return {
      fed: fed, cg: cg, ordRate: ordRate, rocShare: rocShare, dist: dist, deduction: deduction,
      capped: deduction < REIT_DEDUCTION * ordinary - 0.005, weighted: weighted, after: after,
      tey: fullRate < 1 ? after / (1 - fullRate) : NaN, qey: qualRate < 1 ? after / (1 - qualRate) : NaN,
      tax: dist * weighted, ordinaryTotal: ordTotal
    };
  }

  function num(id) {
    var v = parseFloat(document.getElementById(id).value);
    return isNaN(v) ? NaN : v;
  }
  function set(id, text) { document.getElementById(id).textContent = text; }
  function clearRows(id) {
    var body = document.getElementById(id);
    while (body.firstChild) body.removeChild(body.firstChild);
    return body;
  }

  function update() {
    var o = {
      status: document.getElementById('rtStatus').value, income: num('rtIncome'), yield: num('rtYield') / 100,
      ordShare: num('rtOrdinary') / 100, cgShare: num('rtGains') / 100, state: num('rtState') / 100,
      niit: document.getElementById('rtNiit').checked, amount: num('rtAmount')
    };
    var error = document.getElementById('rtError');
    var msg = '';
    if ([o.income, o.yield, o.ordShare, o.cgShare, o.state, o.amount].some(isNaN)) msg = 'Fill in every field with a number.';
    else if (o.income < 0 || o.amount < 0) msg = 'Amounts cannot be negative.';
    else if (o.yield < 0 || o.yield > 0.3) msg = 'Enter a distribution yield from 0 to 30%.';
    else if (o.ordShare < 0 || o.cgShare < 0 || o.ordShare + o.cgShare > 1.00001) msg = 'The ordinary and capital gain shares must be 0% or more and add up to no more than 100%.';
    else if (o.state < 0 || o.state > 0.2) msg = 'Enter a state rate from 0 to 20%.';
    error.hidden = !msg;
    error.textContent = msg;
    var ids = ['rtAfter', 'rtTey', 'rtQey', 'rtWeighted', 'rtOrdRate', 'rtRoc', 'rtDist', 'rtTax', 'rtNet', 'rtBracket'];
    if (msg) {
      ids.forEach(function (id) { set(id, '–'); });
      document.getElementById('rtNote').hidden = true;
      clearRows('rtTable');
      return;
    }
    var a = analyse(o);
    set('rtAfter', pct(a.after, 3));
    set('rtTey', isNaN(a.tey) ? '–' : pct(a.tey, 3));
    set('rtQey', isNaN(a.qey) ? '–' : pct(a.qey, 3));
    set('rtWeighted', pct(a.weighted));
    set('rtOrdRate', pct(a.ordRate, 1) + ' (bracket ' + pct(a.fed, 0) + ')');
    set('rtRoc', pct(a.rocShare, 0));
    set('rtDist', money.format(a.dist));
    set('rtTax', money.format(a.tax));
    set('rtNet', money.format(a.dist - a.tax));
    set('rtBracket', pct(a.fed, 0) + ' ordinary, ' + pct(a.cg, 0) + ' capital gains');
    var note = document.getElementById('rtNote');
    note.hidden = false;
    if (a.capped) note.textContent = 'Your REIT dividends are large next to your taxable income, so the 20% deduction is capped at 20% of taxable income (' + money0.format(a.deduction) + ').';
    else if (a.rocShare > 0) note.textContent = 'The ' + pct(a.rocShare, 0) + ' return of capital is not taxed now, but it lowers your cost basis, so it adds to your capital gain when you sell.';
    else note.textContent = 'The 20% deduction lowers the federal rate on ordinary REIT dividends from ' + pct(a.fed, 0) + ' to ' + pct(a.ordRate, 1) + '.';

    var body = clearRows('rtTable');
    var limits = BRACKETS[o.status], lower = 0;
    RATES.forEach(function (rate, i) {
      var upper = i < limits.length ? limits[i] : Infinity;
      var r = analyse(o, rate);
      var range = upper === Infinity ? 'Over ' + money0.format(lower) : money0.format(lower === 0 ? 0 : lower + 1) + ' – ' + money0.format(upper);
      var tr = document.createElement('tr');
      [pct(rate, 0), range, pct(r.ordRate, 1), pct(r.after, 3), isNaN(r.tey) ? '–' : pct(r.tey, 3)].forEach(function (t, k) {
        var td = document.createElement(k === 0 ? 'th' : 'td');
        if (k === 0) td.setAttribute('scope', 'row');
        td.textContent = t;
        tr.appendChild(td);
      });
      body.appendChild(tr);
      lower = upper;
    });
  }

  document.addEventListener('DOMContentLoaded', function () {
    var form = document.getElementById('rtForm');
    form.addEventListener('input', update);
    form.addEventListener('change', update);
    form.addEventListener('submit', function (e) { e.preventDefault(); });
    update();
  });
})();
